const VERSION='ke-chuyen-v7';
self.addEventListener('install',event=>{event.waitUntil(caches.open(VERSION).then(cache=>cache.addAll(['./','./index.html','./style.css','./app.js','./audio-player.js','./bookshelf.js','./book-store.js','./books.json','./icons/icon-192.png','./icons/icon-512.png','./icons/apple-touch-icon.png','./icons/favicon-32.png','./manifest.webmanifest','./catalog.json'])));self.skipWaiting();});
self.addEventListener('activate',event=>event.waitUntil(self.clients.claim()));
self.addEventListener('message',event=>{if(event.data?.type==='CACHE_CHAPTER'&&Number.isInteger(event.data.number)&&event.data.number>0)event.waitUntil(caches.open(VERSION).then(cache=>cache.add(`./chapters/${event.data.number}.json`)).catch(()=>{}));});
self.addEventListener('fetch',event=>{if(event.request.method!=='GET'||new URL(event.request.url).origin!==self.location.origin||new URL(event.request.url).pathname.includes('/api/')||event.request.headers.has('range')||/\.(mp3|m4a)$/i.test(new URL(event.request.url).pathname))return;event.respondWith(fetch(event.request).then(response=>{if(response.ok){const clone=response.clone();event.waitUntil(caches.open(VERSION).then(cache=>cache.put(event.request,clone)));}return response;}).catch(()=>caches.match(event.request).then(response=>response||new Response('Nội dung chưa được lưu trên thiết bị.',{status:503}))));});
